ALTER TABLE public.peer_review_assessments ADD COLUMN discussion_held_at timestamptz, ADD COLUMN discussion_note text, ADD COLUMN discussion_min_score numeric NOT NULL DEFAULT 8 CHECK (discussion_min_score >= 0 AND discussion_min_score <= 10), ADD COLUMN discussion_deduction integer NOT NULL DEFAULT 0 CHECK (discussion_deduction <= 0), ADD COLUMN discussion_resolved_at timestamptz, ADD COLUMN final_points_adjustment integer NOT NULL DEFAULT 0 CHECK (final_points_adjustment <= 0);
COMMENT ON COLUMN public.peer_review_assessments.final_points_adjustment IS 'Instructor-recorded adjustment to final totals; does not change the peer-review score or compute an overall course grade.';